public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    long[] a = new long[n];

    for (int i = 0; i < n; i++) {
        a[i] = sc.nextLong();
    }

    sc.close();
    long mod = 998244353;
    long[] dp = new long[n];
    dp[0] = 1;

    for (int i = 0; i < n; i++) {
        for (int j = 1; i + j * a[i] < n; j++) {
            dp[(int) (i + j * a[i])] = (dp[(int) (i + j * a[i])] + dp[i]) % mod;
        }
    }

    long ans = 0;

    for (int i = 0; i < n; i++) {
        ans = (ans + dp[i]) % mod;
    }

    System.out.println(ans);
}
